import os
import subprocess

output = {}

# Check if bubblewrap is available and running
try:
    bubblewrap_version = subprocess.check_output(['bwrap', '--version'], stderr=subprocess.STDOUT).decode()
    output['bubblewrap_version'] = bubblewrap_version.strip()
except Exception as e:
    output['bubblewrap_check_error'] = str(e)

# Check for possible mounts and namespaces
try:
    mounts = subprocess.check_output(['mount']).decode()
    output['mounts'] = mounts
except Exception as e:
    output['mounts_error'] = str(e)

# Try to check if we have CAP_SYS_ADMIN or capabilities that might allow mount escape
try:
    capabilities = subprocess.check_output(['capsh', '--print']).decode()
    output['capabilities'] = capabilities
except Exception as e:
    output['capabilities_error'] = str(e)

# List root directory
try:
    root_contents = os.listdir('/root')
    output['root_directory'] = root_contents
except Exception as e:
    output['root_directory_error'] = str(e)

